#include "../../models/film_three_finger_resume/DetectedContactTransfer.h"
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace regrip_three_resume;
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("checkpoint,prefix required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint incomplete");auto r=detectedContactTransfer(s,q,v,time,h);std::string prefix=argv[2];std::ofstream rows(prefix+".rows.csv");rows<<std::setprecision(17)<<"row,finger,triangle,feature,gap_mm,pre_normal_velocity_mm_s,post_normal_velocity_mm_s,impulse_Ns,retained\n";for(unsigned k=0;k<r.all.size();++k){const auto&o=r.all[k];rows<<k<<','<<o.finger<<','<<o.triangle<<','<<o.feature<<','<<r.eventGeometry.gap(k)<<','<<r.eventGeometry.J.row(k).dot(r.pre.v)<<','<<r.impact.state.normalVelocity(k)<<','<<r.impact.state.impulse(k)<<','<<(std::abs(r.impact.state.normalVelocity(k))<=1e-10)<<'\n';}std::ofstream metrics(prefix+".metrics.csv");metrics<<std::setprecision(17)<<"event_time_s,event_bracket_width_s,row_count,active_count,impact_momentum_Ns,impact_energy_loss_Nmm,minimum_stage_gap_mm,linear_balance_Ns,angular_balance_Nmm_s,root_evaluations\n"<<time+r.fractionTime<<','<<r.bracketWidth<<','<<r.all.size()<<','<<r.active.size()<<','<<r.impact.state.momentumResidual<<','<<r.impact.state.energyLoss<<','<<r.minimumGap<<','<<r.linearBalance<<','<<r.angularBalance<<','<<r.rootEvaluations<<'\n';std::ofstream states(prefix+".states.txt");states<<std::setprecision(17)<<"EVENT "<<time+r.fractionTime<<'\n'<<r.pre.q.transpose()<<'\n'<<r.pre.v.transpose()<<'\n'<<r.impact.state.velocity.transpose()<<"\nEND "<<time+h<<'\n'<<r.post.q.transpose()<<'\n'<<r.post.v.transpose()<<'\n';std::cout<<"PASS endpoint-negative detected symmetric smooth-face transfer;NOT global earliest CCD/SOFA/fullcycle\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
